<script>document.getElementById('editMemberModal')?.addEventListener('show.bs.modal',event=>{const button=event.relatedTarget;const form=document.getElementById('editMemberForm');form.action=`{{ url('/members') }}/${button.dataset.memberId}`;document.getElementById('edit_member_name').value=button.dataset.memberName;document.getElementById('edit_member_nickname').value=button.dataset.memberNickname;document.getElementById('edit_member_phone').value=button.dataset.memberPhone;document.getElementById('edit_joined_at').value=button.dataset.memberJoinedAt;document.getElementById('edit_is_active').value=button.dataset.memberActive;document.getElementById('edit_member_photo').value='';const preview=document.getElementById('editMemberPreview');preview.classList.toggle('d-none',!button.dataset.memberPhoto);if(button.dataset.memberPhoto)preview.src=button.dataset.memberPhoto;});for(const [inputId,previewId] of [['member_photo','newMemberPreview'],['edit_member_photo','editMemberPreview']]){document.getElementById(inputId)?.addEventListener('change',event=>{const preview=document.getElementById(previewId);if(event.target.files[0]){preview.src=URL.createObjectURL(event.target.files[0]);preview.classList.remove('d-none');}});}</script>
